/**
 * Standalone Browser DICOM Parser Engine
 * Parses single and multi-slice DICOM (.dcm) files natively in JavaScript.
 */

window.dicomParserEngine = (function() {
  'use strict';

  function isDICOM(buffer) {
    if (buffer.byteLength < 132) return false;
    const view = new DataView(buffer);
    const magic = String.fromCharCode(
      view.getUint8(128), view.getUint8(129), view.getUint8(130), view.getUint8(131)
    );
    return magic === 'DICM';
  }

  function parseDicomHeader(buffer) {
    const view = new DataView(buffer);
    const result = {
      rows: 256,
      cols: 256,
      bitsAllocated: 16,
      pixelRepresentation: 0,
      rescaleIntercept: 0,
      rescaleSlope: 1,
      pixelSpacing: [1.0, 1.0],
      instanceNumber: 1,
      pixelDataOffset: -1,
      pixelDataLength: 0
    };

    let offset = 132; // Skip 128-byte preamble + DICM
    const length = buffer.byteLength;

    while (offset < length - 8) {
      const group = view.getUint16(offset, true);
      const element = view.getUint16(offset + 2, true);

      // Handle Pixel Data tag (0x7FE0, 0x0010)
      if (group === 0x7FE0 && element === 0x0010) {
        const valLength = view.getUint32(offset + 8, true);
        result.pixelDataOffset = offset + 12;
        result.pixelDataLength = valLength > 0 && (offset + 12 + valLength <= length) 
          ? valLength 
          : length - (offset + 12);
        break;
      }

      // Check standard tags
      if (group === 0x0028) {
        if (element === 0x0010) result.rows = view.getUint16(offset + 8, true); // Rows
        if (element === 0x0011) result.cols = view.getUint16(offset + 8, true); // Columns
        if (element === 0x0010 || element === 0x0011) {
          offset += 10; continue;
        }
        if (element === 0x0100) result.bitsAllocated = view.getUint16(offset + 8, true);
        if (element === 0x0103) result.pixelRepresentation = view.getUint16(offset + 8, true);
      }

      if (group === 0x0020 && element === 0x0013) { // Instance Number
        try {
          const len = view.getUint32(offset + 8, true);
          let str = '';
          for (let k = 0; k < Math.min(len, 10); k++) {
            str += String.fromCharCode(view.getUint8(offset + 12 + k));
          }
          const num = parseInt(str.trim(), 10);
          if (!isNaN(num)) result.instanceNumber = num;
        } catch(e){}
      }

      // Skip forward safely
      const explicitVR = String.fromCharCode(view.getUint8(offset + 4), view.getUint8(offset + 5));
      let elementLength = 8;

      if (['OB', 'OW', 'OF', 'SQ', 'UT', 'UN'].includes(explicitVR)) {
        elementLength = 12 + view.getUint32(offset + 8, true);
      } else if (explicitVR.match(/^[A-Z]{2}$/)) {
        elementLength = 8 + view.getUint16(offset + 6, true);
      } else {
        elementLength = 8 + view.getUint32(offset + 4, true);
      }

      if (elementLength <= 0 || isNaN(elementLength)) elementLength = 4;
      offset += elementLength;
    }

    if (result.pixelDataOffset === -1) {
      // Fallback: estimate pixel data offset at end of buffer
      const expectedBytes = result.rows * result.cols * (result.bitsAllocated / 8);
      result.pixelDataOffset = Math.max(132, length - expectedBytes);
      result.pixelDataLength = length - result.pixelDataOffset;
    }

    return result;
  }

  function readDicomPixels(buffer, header) {
    const view = new DataView(buffer, header.pixelDataOffset);
    const count = header.rows * header.cols;
    const pixels = new Float32Array(count);
    const isSigned = header.pixelRepresentation === 1;

    for (let i = 0; i < count; i++) {
      if (header.pixelDataOffset + i * 2 >= buffer.byteLength) break;
      let val = isSigned ? view.getInt16(i * 2, true) : view.getUint16(i * 2, true);
      pixels[i] = val * header.rescaleSlope + header.rescaleIntercept;
    }

    return pixels;
  }

  return {
    isDICOM,
    parseDicomHeader,
    readDicomPixels
  };
})();
